import {CLOUD_URL,CLOUD_KEY} from '../auth/config.js';
const form=document.querySelector('#form'),msg=document.querySelector('#message');
form.onsubmit=async e=>{e.preventDefault();const f=new FormData(form);msg.textContent='啟用中…';try{const r=await fetch(`${CLOUD_URL}/functions/v1/tp927-bootstrap`,{method:'POST',headers:{apikey:CLOUD_KEY,'content-type':'application/json'},body:JSON.stringify({code:f.get('code'),password:f.get('password')})});const data=await r.json();if(!r.ok)throw Error(data.error||'啟用失敗');form.reset();msg.innerHTML='管理者已建立。<a href="./cloud.html">前往登入</a>。'}catch(x){msg.textContent=x.message}};
